        _require_data_root(data_root),
        schemas,
        workspace_root=_workspace_root(args),
        dry_run=args.dry_run,
    )
    return {
        "ok": True,
        "dry_run": bool(args.dry_run),
        "plan": plan,
        "activates_character": False,
    }


def _handle_pack_list(
    args: argparse.Namespace,
    data_root: Path | None,
